def gen_replay_big(rng):
    nn = rng.randint(2, 12)
    nodes = ['node_%d' % i for i in range(nn)]
    caps = {n: rng.choice([0, 1, 2, 3, 512, rng.randint(0, 12)]) for n in nodes}
    nf = rng.randint(0, 40)
    flows = [make_flow(rng, nodes, 'f%03d' % i) for i in range(nf)]
    events = []
    for _ in range(rng.randint(0, 400)):
        r = rng.random()
        if r < 0.25 and flows:
            f = rng.choice(flows)
            events.append({'op': 'put', 'flow': f['id'], 'node': rng.choice(f['path'])})
        elif r < 0.45 and flows:
            events.append({'op': 'enable', 'flow': rng.choice(flows)['id']})
        elif r < 0.55 and flows:
            events.append({'op': 'disable', 'flow': rng.choice(flows)['id']})
        elif r < 0.6:
            events.append({'op': 'reset'})
        elif flows:
            f = rng.choice(flows)
            events.append({'op': 'packet', 'flow': f['id'],
                           'header': header_for(rng, f), 'payload': payload_for(rng)})
        else:
            events.append({'op': 'reset'})
    return {'mode': 'replay', 'capacities': caps, 'flows': flows, 'events': events}


def gen_plan_big(rng, nf=None, nn=None, pathlen=None):
    nn = nn if nn is not None else rng.randint(2, 12)
    nodes = ['node_%d' % i for i in range(nn)]
    caps = {n: rng.choice([0, 1, 1, 2, 2, 3, 512, rng.randint(0, 8)]) for n in nodes}
    nf = nf if nf is not None else rng.randint(0, 22)
    flows = []
    for i in range(nf):
        if pathlen is not None and pathlen <= len(nodes):
            N = pathlen
        else:
            N = rng.randint(2, min(9, len(nodes)))
        f = make_flow(rng, nodes, 'f%03d' % i)
        f['path'] = rng.sample(nodes, N)
        del f['labels']
        flows.append(f)
    offers = {}
    for f in flows:
        runs = []
        for _ in range(rng.randint(0, 8)):
            runs.append({'header': header_for(rng, f), 'count': rng.randint(1, 100)})
        offers[f['id']] = runs
    pinned = []
    if flows and rng.random() < 0.4:
        pinned = rng.sample([f['id'] for f in flows], rng.randint(1, min(4, len(flows))))
    return {'mode': 'plan', 'capacities': caps, 'flows': flows,
            'warmup': rng.choice([0, 0, 1, 2, 5, 30, 200]),
            'pinned': pinned, 'offers': offers}


def gen_plan_hard(rng, nf=22, nn=8, pathlen=6, equal=True, cap=3):
    """Adversarial: many equal-benefit flows, tight overlapping capacities."""
    nodes = ['n%d' % i for i in range(nn)]
    caps = {n: cap for n in nodes}
    flows = []
    for i in range(nf):
        f = make_flow(rng, nodes, 'f%02d' % i)
        f['path'] = rng.sample(nodes, pathlen)
        del f['labels']
        flows.append(f)
    offers = {}
    for f in flows:
        runs = []
        for _ in range(rng.randint(1, 4)):
            hdr = header_for(rng, f, 'match')
            b = bytearray.fromhex(hdr)
            b[f['kinds'].index('T')] = 200
            b[f['kinds'].index('Q')] = 3
            for j, c in enumerate(f['kinds']):
                if c == 'K':
                    b[j] = int(f['template'][2*j:2*j+2], 16)
            runs.append({'header': bytes(b).hex(), 'count': 1 if equal else rng.randint(1, 5)})
        offers[f['id']] = runs
    return {'mode': 'plan', 'capacities': caps, 'flows': flows,
            'warmup': 0, 'pinned': [], 'offers': offers}
