import json, subprocess, sys, random
sys.path.insert(0, '/workspace/dev')
import gen as G

def run(path, data):
    return subprocess.run([sys.executable, '-I', '-B', path], input=data,
                          text=True, capture_output=True, timeout=900)

def main():
    which = sys.argv[1]
    n = int(sys.argv[2]); start = int(sys.argv[3])
    batch = 20
    bad = 0
    seeds = list(range(start, start + n))
    for i in range(0, len(seeds), batch):
        chunk = seeds[i:i+batch]
        lines = []
        for seed in chunk:
            rng = random.Random(seed * 7919 + 13)
            if which == 'replay_big': req = G.gen_replay_big(rng)
            elif which == 'plan_big': req = G.gen_plan_big(rng)
            elif which == 'plan_hard': req = G.gen_plan_hard(rng)
            else: raise SystemExit('?')
            lines.append(json.dumps(req))
        data = ''.join(l + '\n' for l in lines)
        r = run('/workspace/submission/main.py', data)
        e = run('/workspace/dev/ref.py', data)
        if r.returncode or e.returncode:
            print('CRASH', chunk[0], r.stderr[-1500:], e.stderr[-1500:]); bad += 1; break
        gl = r.stdout.splitlines(); el = e.stdout.splitlines()
        if len(gl) != len(lines) or len(el) != len(lines):
            print('COUNT', len(gl), len(el)); bad += 1; break
        for k, seed in enumerate(chunk):
            if gl[k] != el[k]:
                bad += 1
                print('MISMATCH seed', seed, 'line saved')
                open('/workspace/tmp/bad.json','w').write(lines[k])
                print('  got', gl[k][:400]); print('  exp', el[k][:400])
                if bad > 3: break
        if bad > 3: break
    print(which, 'checked', n, 'mismatches', bad)
    return 1 if bad else 0

sys.exit(main())
